/** The motifs whose grid isn't 16 x 16, by size ("WxH": space-separated names). */
const GRIDS: Record<string, string> = {
  '24x24':
    'cards-item-tile cards-ledger cards-magnifier-24 cards-printer cards-scroll-open-24 cards-scroll-ticked-24 cards-seal-bell cards-seal-chest cards-seal-coins cards-seal-star cards-spellbook-inuse cards-spellbook-suggested flows-campfire flows-clipboard-empty flows-clipboard-filled flows-cracked-gear flows-door-in flows-door-out flows-faded-clock flows-lightbulb flows-moon-stars flows-padlock-locked flows-padlock-open flows-patch-scroll flows-question-cloud flows-sunrise now-campfire v2-map-gate v2-systems-pot-24',
  '32x28': 'flows-notice-board',
  '32x32':
    'cards-cheer cards-mascot-cheer cards-mascot-talk cards-mascot-think flows-gremlin flows-guide-blob flows-sleeping-blob flows-walking-blob v2-character-mannequin',
  '48x11': 'now-wordmark',
  '8x8':
    'cards-pip cards-speech-tail-left cards-speech-tail-right cards-zz flows-now-cap flows-overflow-spark',
};

/** A motif's grid, before its group has loaded (so a placeholder already has the right size). */
export function gridOf(name: string): readonly [number, number] {
  for (const [size, names] of Object.entries(GRIDS))
    if (` ${names} `.includes(` ${name} `)) {
      const [w = 16, h = 16] = size.split('x').map(Number);
      return [w, h];
    }
  return [16, 16];
}

/** The lazy group that holds a motif, from its name ("v2-systems-…" is systems, "cards-…" is cards). */
export const groupOf = (name: string): ArtGroup =>
  (name.startsWith('v2-') ? name.split('-')[1] : name.split('-')[0]) as ArtGroup;
